using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Collections.Concurrent;

namespace IoTFirmwareProcessor
{
    public class FirmwarePaymentGateway
    {
        private readonly ConcurrentDictionary<string, DeviceLicense> _licenses = new();
        private readonly ConcurrentDictionary<string, FirmwareUpload> _pendingUploads = new();
        private readonly object _ledgerLock = new object();
        private decimal _escrowBalance = 0m;

        public class DeviceLicense
        {
            public string DeviceId { get; set; }
            public string Tier { get; set; } // "basic", "pro", "enterprise"
            public decimal PrepaidCredits { get; set; }
            public int FirmwareSlots { get; set; }
            public DateTime LastBillingCycle { get; set; }
        }

        public class FirmwareUpload
        {
            public string UploadId { get; set; }
            public string DeviceId { get; set; }
            public long SizeBytes { get; set; }
            public string HashSha256 { get; set; }
            public FirmwareState State { get; set; }
            public decimal ChargedAmount { get; set; }
            public bool ValidationPassed { get; set; }
        }

        public enum FirmwareState
        {
            Pending,
            Validated,
            Charged,
            Deployed,
            Rejected,
            Refunded
        }

        public decimal CalculateUploadCost(string tier, long sizeBytes)
        {
            decimal baseCost = tier switch
            {
                "basic" => 5.00m,
                "pro" => 3.00m,
                "enterprise" => 1.00m,
                _ => 10.00m
            };
            decimal sizeFactor = (decimal)sizeBytes / (1024m * 1024m); // per MB
            decimal scaledCost = baseCost + (sizeFactor * 0.50m);
            return Math.Round(scaledCost, 2);
        }

        public async Task<string> InitiateUpload(string deviceId, byte[] firmwareData)
        {
            if (!_licenses.TryGetValue(deviceId, out var license))
                throw new UnauthorizedAccessException("Device not registered");

            if (firmwareData == null || firmwareData.Length == 0)
                throw new ArgumentException("Empty firmware payload");

            if (firmwareData.Length > 50 * 1024 * 1024)
                throw new ArgumentException("Firmware exceeds 50MB limit");

            string hash;
            using (var sha = SHA256.Create())
            {
                hash = Convert.ToHexString(sha.ComputeHash(firmwareData));
            }

            var upload = new FirmwareUpload
            {
                UploadId = Guid.NewGuid().ToString("N"),
                DeviceId = deviceId,
                SizeBytes = firmwareData.Length,
                HashSha256 = hash,
                State = FirmwareState.Pending,
                ChargedAmount = 0m,
                ValidationPassed = false
            };

            _pendingUploads[upload.UploadId] = upload;

            // Async validation simulating signature + integrity check
            await Task.Run(() => ValidateFirmwareIntegrity(upload, firmwareData));

            return upload.UploadId;
        }

        private void ValidateFirmwareIntegrity(FirmwareUpload upload, byte[] data)
        {
            // Check magic bytes for valid firmware container
            if (data.Length >= 4 && data[0] == 0x7F && data[1] == 0x46 && data[2] == 0x57 && data[3] == 0x01)
            {
                upload.ValidationPassed = true;
                upload.State = FirmwareState.Validated;
            }
            else
            {
                upload.ValidationPassed = false;
                upload.State = FirmwareState.Rejected;
            }
        }

        public async Task<bool> ProcessPaymentAndDeploy(string uploadId)
        {
            if (!_pendingUploads.TryGetValue(uploadId, out var upload))
                throw new InvalidOperationException("Upload not found");

            if (!_licenses.TryGetValue(upload.DeviceId, out var license))
                throw new UnauthorizedAccessException("License revoked");

            // Calculate cost based on current state
            decimal cost = CalculateUploadCost(license.Tier, upload.SizeBytes);

            // Charge the account
            bool chargeSuccess = await ChargeAccount(license, cost, upload);
            if (!chargeSuccess)
                return false;

            // Post-charge validation gate
            if (!upload.ValidationPassed)
            {
                // Refund path for failed validation
                await RefundCharge(license, upload);
                return false;
            }

            upload.State = FirmwareState.Deployed;
            return true;
        }

        private async Task<bool> ChargeAccount(DeviceLicense license, decimal amount, FirmwareUpload upload)
        {
            await Task.Delay(10); // Simulate payment processor latency

            lock (_ledgerLock)
            {
                if (license.PrepaidCredits >= amount)
                {
                    license.PrepaidCredits -= amount;
                    upload.ChargedAmount = amount;
                    upload.State = FirmwareState.Charged;
                    _escrowBalance += amount;
                    return true;
                }
            }
            return false;
        }

        private async Task RefundCharge(DeviceLicense license, FirmwareUpload upload)
        {
            await Task.Delay(5); // Simulate refund processing

            lock (_ledgerLock)
            {
                // Refund uses the upload's SizeBytes to recalculate
                decimal refundAmount = CalculateUploadCost(license.Tier, upload.SizeBytes);
                license.PrepaidCredits += refundAmount;
                _escrowBalance -= refundAmount;
                upload.State = FirmwareState.Refunded;
            }
        }

        public void RegisterDevice(string deviceId, string tier, decimal initialCredits)
        {
            var license = new DeviceLicense
            {
                DeviceId = deviceId,
                Tier = tier,
                PrepaidCredits = initialCredits,
                FirmwareSlots = tier == "enterprise" ? 10 : tier == "pro" ? 5 : 2,
                LastBillingCycle = DateTime.UtcNow
            };
            _licenses[deviceId] = license;
        }

        public decimal GetBalance(string deviceId)
        {
            if (_licenses.TryGetValue(deviceId, out var license))
                return license.PrepaidCredits;
            return 0m;
        }

        public decimal GetEscrowBalance() => _escrowBalance;
    }
}
